-- Anaira AI Growth Engine Phase 3: provider integration infrastructure and durable jobs.
-- This migration has already been applied to Anaira's connected production Supabase project.
alter table public.growth_social_accounts add column if not exists encrypted_credentials text, add column if not exists token_expires_at timestamptz, add column if not exists scopes text[] not null default '{}', add column if not exists last_synced_at timestamptz, add column if not exists last_error text;
create table if not exists public.growth_oauth_states (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.growth_organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,provider text not null check(provider in ('meta')),state_hash text not null unique,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now());
create index if not exists growth_oauth_state_expiry_idx on public.growth_oauth_states(expires_at) where used_at is null;
create table if not exists public.growth_webhook_events (id uuid primary key default gen_random_uuid(),organization_id uuid references public.growth_organizations(id) on delete cascade,provider text not null,event_type text not null,payload jsonb not null default '{}'::jsonb,processing_status text not null default 'received' check(processing_status in ('received','processing','processed','ignored','failed')),error_message text,received_at timestamptz not null default now(),processed_at timestamptz,event_key text);
create unique index if not exists growth_webhook_event_key_unique on public.growth_webhook_events(provider,event_key);
create index if not exists growth_webhook_events_provider_status_idx on public.growth_webhook_events(provider,processing_status,received_at);
create table if not exists public.growth_jobs (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.growth_organizations(id) on delete cascade,job_type text not null check(job_type in ('publish_content','send_whatsapp','send_email','execute_rule')),payload jsonb not null default '{}'::jsonb,status text not null default 'queued' check(status in ('queued','processing','succeeded','failed','cancelled')),run_at timestamptz not null default now(),attempts integer not null default 0,max_attempts integer not null default 5,last_error text,locked_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create index if not exists growth_jobs_due_idx on public.growth_jobs(run_at,created_at) where status='queued';
create index if not exists growth_jobs_org_idx on public.growth_jobs(organization_id,status,created_at desc);
alter table public.growth_oauth_states enable row level security; alter table public.growth_webhook_events enable row level security; alter table public.growth_jobs enable row level security;
create policy growth_oauth_states_manager_read on public.growth_oauth_states for select to authenticated using (private.is_growth_manager(organization_id) or public.is_anaira_admin());
create policy growth_webhook_events_manager_read on public.growth_webhook_events for select to authenticated using (private.is_growth_manager(organization_id) or public.is_anaira_admin());
create policy growth_jobs_manager_read on public.growth_jobs for select to authenticated using (private.is_growth_manager(organization_id) or public.is_anaira_admin());
grant select on public.growth_oauth_states,public.growth_webhook_events,public.growth_jobs to authenticated;
revoke insert,update,delete on public.growth_oauth_states,public.growth_webhook_events,public.growth_jobs from authenticated;
create or replace function public.claim_growth_jobs(batch_limit integer default 10) returns setof public.growth_jobs language plpgsql security definer set search_path=pg_catalog,public as $$ begin return query with picked as (select id from public.growth_jobs where status='queued' and run_at<=now() and attempts<max_attempts order by run_at,created_at for update skip locked limit greatest(1,least(batch_limit,50))), claimed as (update public.growth_jobs j set status='processing',locked_at=now(),attempts=attempts+1 from picked where j.id=picked.id returning j.*) select * from claimed; end; $$;
revoke all on function public.claim_growth_jobs(integer) from public,anon,authenticated; grant execute on function public.claim_growth_jobs(integer) to service_role;
